def evaluate(self, *args, **kw):
    op = self.op
    args, kw = self._get_kwarg_model_parameters_as_positional(args, kw)
    left_inputs = self._get_left_inputs_from_args(args)
    left_params = self._get_left_params_from_args(args)

    if op == 'fix_inputs':
        pos_index = dict(zip(self.left.inputs, range(self.left.n_inputs)))
        fixed_inputs = {
            key if np.issubdtype(type(key), np.integer) else pos_index[key]: value
            for key, value in self.right.items()
        }
        left_inputs = [
            fixed_inputs[ind] if ind in fixed_inputs.keys() else inp
            for ind, inp in enumerate(left_inputs)
        ]

    leftval = self.left.evaluate(*itertools.chain(left_inputs, left_params))

    if op == 'fix_inputs':
        return leftval

    right_inputs = self._get_right_inputs_from_args(args)
    right_params = self._get_right_params_from_args(args)

    if op == "|":
        if isinstance(leftval, tuple):
            return self.right.evaluate(*itertools.chain(leftval, right_params))
        else:
            return self.right.evaluate(leftval, *right_params)
    else:
        rightval = self.right.evaluate(*itertools.chain(right_inputs, right_params))

    return self._apply_operators_to_value_lists(leftval, rightval, **kw)

def n_inputs(self):
    """ The number of inputs of a model."""
    return self._n_inputs

def n_outputs(self):
    """ The number of outputs of a model."""
    return self._n_outputs

def create_model(self, model):
    """
    Create a table and any accompanying indexes or unique constraints for
    the given `model`.
    """
    # Create column SQL, add FK deferreds if needed
    column_sqls = []
    params = []
    for field in model._meta.local_fields:
        # SQL
        definition, extra_params = self.column_sql(model, field)
        if definition is None:
            continue
        # Check constraints can go on the column SQL here
        db_params = field.db_parameters(connection=self.connection)
        if db_params['check']:
            definition += " " + self.sql_check_constraint % db_params
        # Autoincrement SQL (for backends with inline variant)
        col_type_suffix = field.db_type_suffix(connection=self.connection)
        if col_type_suffix:
            definition += " %s" % col_type_suffix
        params.extend(extra_params)
        # FK
        if field.remote_field and field.db_constraint:
            to_table = field.remote_field.model._meta.db_table
            to_column = field.remote_field.model._meta.get_field(field.remote_field.field_name).column
            if self.sql_create_inline_fk:
                definition += " " + self.sql_create_inline_fk % {
                    "to_table": self.quote_name(to_table),
                    "to_column": self.quote_name(to_column),
                }
            elif self.connection.features.supports_foreign_keys:
                self.deferred_sql.append(self._create_fk_sql(model, field, "_fk_%(to_table)s_%(to_column)s"))
        # Add the SQL to our big list
        column_sqls.append("%s %s" % (
            self.quote_name(field.column),
            definition,
        ))
        # Autoincrement SQL (for backends with post table definition variant)
        if field.get_internal_type() in ("AutoField", "BigAutoField"):
            autoinc_sql = self.connection.ops.autoinc_sql(model._meta.db_table, field.column)
            if autoinc_sql:
                self.deferred_sql.extend(autoinc_sql)

    # Add any unique_togethers (always deferred, as some fields might be
    # created afterwards, like geometry fields with some backends)
    for fields in model._meta.unique_together:
        columns = [model._meta.get_field(field).column for field in fields]
        self.deferred_sql.append(self._create_unique_sql(model, columns))
    constraints = [constraint.constraint_sql(model, self) for constraint in model._meta.constraints]
    # Make the table
    sql = self.sql_create_table % {
        "table": self.quote_name(model._meta.db_table),
        "definition": ", ".join(constraint for constraint in (*column_sqls, *constraints) if constraint),
    }
    if model._meta.db_tablespace:
        tablespace_sql = self.connection.ops.tablespace_sql(model._meta.db_tablespace)
        if tablespace_sql:
            sql += ' ' + tablespace_sql
    # Prevent using [] as params, in the case a literal '%' is used in the definition
    self.execute(sql, params or None)

    # Add any field index and index_together's (deferred as SQLite _remake_table needs it)
    self.deferred_sql.extend(self._model_indexes_sql(model))

    # Make M2M tables
    for field in model._meta.local_many_to_many:
        if field.remote_field.through._meta.auto_created:
            self.create_model(field.remote_field.through)

def apply_migration(self, state, migration, fake=False, fake_initial=False):
    """Run a migration forwards."""
    migration_recorded = False
    if self.progress_callback:
        self.progress_callback("apply_start", migration, fake)
    if not fake:
        if fake_initial:
            # Test to see if this is an already-applied initial migration
            applied, state = self.detect_soft_applied(state, migration)
            if applied:
                fake = True
        if not fake:
            # Alright, do it normally
            with self.connection.schema_editor(atomic=migration.atomic) as schema_editor:
                state = migration.apply(state, schema_editor)
                self.record_migration(migration)
                migration_recorded = True
    if not migration_recorded:
        self.record_migration(migration)
    # Report progress
    if self.progress_callback:
        self.progress_callback("apply_success", migration, fake)
    return state

def _find_reload_model(self, app_label, model_name, delay=False):
    if delay:
        self.is_delayed = True

    related_models = set()

    try:
        old_model = self.apps.get_model(app_label, model_name)
    except LookupError:
        pass
    else:
        # Get all relations to and from the old model before reloading,
        # as _meta.apps may change
        if delay:
            related_models = get_related_models_tuples(old_model)
        else:
            related_models = get_related_models_recursive(old_model)

    # Get all outgoing references from the model to be rendered
    model_state = self.models[(app_label, model_name)]
    # Directly related models are the models pointed to by ForeignKeys,
    # OneToOneFields, and ManyToManyFields.
    direct_related_models = set()
    for name, field in model_state.fields:
        if field.is_relation:
            if field.remote_field.model == RECURSIVE_RELATIONSHIP_CONSTANT:
                continue
            rel_app_label, rel_model_name = _get_app_label_and_model_name(field.related_model, app_label)
            direct_related_models.add((rel_app_label, rel_model_name.lower()))

    # For all direct related models recursively get all related models.
    related_models.update(direct_related_models)
    for rel_app_label, rel_model_name in direct_related_models:
        try:
            rel_model = self.apps.get_model(rel_app_label, rel_model_name)
        except LookupError:
            pass
        else:
            if delay:
                related_models.update(get_related_models_tuples(rel_model))
            else:
                related_models.update(get_related_models_recursive(rel_model))

    # Include the model itself
    related_models.add((app_label, model_name))

    return related_models

def reload_models(self, models, delay=True):
    if 'apps' in self.__dict__:  # hasattr would cache the property
        related_models = set()
        for app_label, model_name in models:
            related_models.update(self._find_reload_model(app_label, model_name, delay))
        self._reload(related_models)

def _reload(self, related_models):
    # Unregister all related models
    with self.apps.bulk_update():
        for rel_app_label, rel_model_name in related_models:
            self.apps.unregister_model(rel_app_label, rel_model_name)

    states_to_be_rendered = []
    # Gather all models states of those models that will be rerendered.
    # This includes:
    # 1. All related models of unmigrated apps
    for model_state in self.apps.real_models:
        if (model_state.app_label, model_state.name_lower) in related_models:
            states_to_be_rendered.append(model_state)

    # 2. All related models of migrated apps
    for rel_app_label, rel_model_name in related_models:
        try:
            model_state = self.models[rel_app_label, rel_model_name]
        except KeyError:
            pass
        else:
            states_to_be_rendered.append(model_state)

    # Render all models
    self.apps.render_multiple(states_to_be_rendered)

def concrete_apps(self):
    self.apps = StateApps(self.real_apps, self.models, ignore_swappable=True)
    return self.apps

def from_apps(cls, apps):
    """Take an Apps and return a ProjectState matching it."""
    app_models = {}
    for model in apps.get_models(include_swapped=True):
        model_state = ModelState.from_model(model)
        app_models[(model_state.app_label, model_state.name_lower)] = model_state
    return cls(app_models)

def process_rhs(self, compiler, connection):
    value = self.rhs
    if self.bilateral_transforms:
        if self.rhs_is_direct_value():
            # Do not call get_db_prep_lookup here as the value will be
            # transformed before being used for lookup
            value = Value(value, output_field=self.lhs.output_field)
        value = self.apply_bilateral_transforms(value)
        value = value.resolve_expression(compiler.query)
    if hasattr(value, 'as_sql'):
        return compiler.compile(value)
    else:
        return self.get_db_prep_lookup(value, connection)

def get_prep_lookup(self):
    if hasattr(self.rhs, 'resolve_expression'):
        return self.rhs
    if self.prepare_rhs and hasattr(self.lhs.output_field, 'get_prep_value'):
        return self.lhs.output_field.get_prep_value(self.rhs)
    return self.rhs

def process_rhs(self, compiler, connection):
    if self.rhs_is_direct_value():
        # rhs should be an iterable of values. Use batch_process_rhs()
        # to prepare/transform those values.
        return self.batch_process_rhs(compiler, connection)
    else:
        return super().process_rhs(compiler, connection)

def collapse_group_by(self, expressions, having):
    # If the DB can group by primary key, then group by the primary key of
    # query's main model. Note that for PostgreSQL the GROUP BY clause must
    # include the primary key of every table, but for MySQL it is enough to
    # have the main table's primary key.
    if self.connection.features.allows_group_by_pk:
        # Determine if the main model's primary key is in the query.
        pk = None
        for expr in expressions:
            # Is this a reference to query's base table primary key? If the
            # expression isn't a Col-like, then skip the expression.
            if (getattr(expr, 'target', None) == self.query.model._meta.pk and
                    getattr(expr, 'alias', None) == self.query.base_table):
                pk = expr
                break
        # If the main model's primary key is in the query, group by that
        # field, HAVING expressions, and expressions associated with tables
        # that don't have a primary key included in the grouped columns.
        if pk:
            pk_aliases = {
                expr.alias for expr in expressions
                if hasattr(expr, 'target') and expr.target.primary_key
            }
            expressions = [pk] + [
                expr for expr in expressions
                if expr in having or (
                    getattr(expr, 'alias', None) is not None and expr.alias not in pk_aliases
                )
            ]
    elif self.connection.features.allows_group_by_selected_pks:
        # Filter out all expressions associated with a table's primary key
        # present in the grouped columns. This is done by identifying all
        # tables that have their primary key included in the grouped
        # columns and removing non-primary key columns referring to them.
        # Unmanaged models are excluded because they could be representing
        # database views on which the optimization might not be allowed.
        pks = {
            expr for expr in expressions
            if (
                hasattr(expr, 'target') and
                expr.target.primary_key and
                self.connection.features.allows_group_by_selected_pks_on_model(expr.target.model)
            )
        }
        aliases = {expr.alias for expr in pks}
        expressions = [
            expr for expr in expressions if expr in pks or getattr(expr, 'alias', None) not in aliases
        ]
    return expressions

def get_group_by_cols(self, alias=None):
    if alias:
        return [Ref(alias, self)]
    external_cols = self.query.get_external_cols()
    if any(col.possibly_multivalued for col in external_cols):
        return [self]
    return external_cols

def get_external_cols(self):
    exprs = chain(self.annotations.values(), self.where.children)
    return [
        col for col in self._gen_cols(exprs)
        if col.alias in self.external_aliases
    ]

def _gen_cols(cls, exprs):
    for expr in exprs:
        if isinstance(expr, Col):
            yield expr
        else:
            yield from cls._gen_cols(expr.get_source_expressions())

def resolve(self, path):
    path = str(path)  # path may be a reverse_lazy object
    tried = []
    match = self.pattern.match(path)
    if match:
        new_path, args, kwargs = match
        for pattern in self.url_patterns:
            try:
                sub_match = pattern.resolve(new_path)
            except Resolver404 as e:
                sub_tried = e.args[0].get('tried')
                if sub_tried is not None:
                    tried.extend([pattern] + t for t in sub_tried)
                else:
                    tried.append([pattern])
            else:
                if sub_match:
                    # Merge captured arguments in match with submatch
                    sub_match_dict = {**kwargs, **self.default_kwargs}
                    # Update the sub_match_dict with the kwargs from the sub_match.
                    sub_match_dict.update(sub_match.kwargs)
                    # If there are *any* named groups, ignore all non-named groups.
                    # Otherwise, pass all non-named arguments as positional arguments.
                    sub_match_args = sub_match.args
                    if not sub_match_dict:
                        sub_match_args = args + sub_match.args
                    current_route = '' if isinstance(pattern, URLPattern) else str(pattern.pattern)
                    return ResolverMatch(
                        sub_match.func,
                        sub_match_args,
                        sub_match_dict,
                        sub_match.url_name,
                        [self.app_name] + sub_match.app_names,
                        [self.namespace] + sub_match.namespaces,
                        self._join_route(current_route, sub_match.route),
                    )
                tried.append([pattern])
        raise Resolver404({'tried': tried, 'path': new_path})
    raise Resolver404({'path': path})

def resolve(self, path):
    match = self.pattern.match(path)
    if match:
        new_path, args, kwargs = match
        # Pass any extra_kwargs as **kwargs.
        kwargs.update(self.default_args)
        return ResolverMatch(self.callback, args, kwargs, self.pattern.name, route=str(self.pattern))

def match(self, path):
    match = self.regex.search(path)
    if match:
        # If there are any named groups, use those as kwargs, ignoring
        # non-named groups. Otherwise, pass all non-named arguments as
        # positional arguments.
        kwargs = {k: v for k, v in match.groupdict().items() if v is not None}
        args = () if kwargs else match.groups()
        return path[match.end():], args, kwargs
    return None

def match(self, path):
    match = self.regex.search(path)
    if match:
        # RoutePattern doesn't allow non-named groups so args are ignored.
        kwargs = match.groupdict()
        for key, value in kwargs.items():
            converter = self.converters[key]
            try:
                kwargs[key] = converter.to_python(value)
            except ValueError:
                return None
        return path[match.end():], (), kwargs
    return None

def match(self, path):
    language_prefix = self.language_prefix
    if path.startswith(language_prefix):
        return path[len(language_prefix):], (), {}
    return None

def _is_callback(self, name):
    if not self._populated:
        self._populate()
    return name in self._callback_strs

def _populate(self):
    # Short-circuit if called recursively in this thread to prevent
    # infinite recursion. Concurrent threads may call this at the same
    # time and will need to continue, so set 'populating' on a
    # thread-local variable.
    if getattr(self._local, 'populating', False):
        return
    try:
        self._local.populating = True
        lookups = MultiValueDict()
        namespaces = {}
        apps = {}
        language_code = get_language()
        for url_pattern in reversed(self.url_patterns):
            p_pattern = url_pattern.pattern.regex.pattern
            if p_pattern.startswith('^'):
                p_pattern = p_pattern[1:]
            if isinstance(url_pattern, URLPattern):
                self._callback_strs.add(url_pattern.lookup_str)
                bits = normalize(url_pattern.pattern.regex.pattern)
                lookups.appendlist(
                    url_pattern.callback,
                    (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters)
                )
                if url_pattern.name is not None:
                    lookups.appendlist(
                        url_pattern.name,
                        (bits, p_pattern, url_pattern.default_args, url_pattern.pattern.converters)
                    )
            else:  # url_pattern is a URLResolver.
                url_pattern._populate()
                if url_pattern.app_name:
                    apps.setdefault(url_pattern.app_name, []).append(url_pattern.namespace)
                    namespaces[url_pattern.namespace] = (p_pattern, url_pattern)
                else:
                    for name in url_pattern.reverse_dict:
                        for matches, pat, defaults, converters in url_pattern.reverse_dict.getlist(name):
                            new_matches = normalize(p_pattern + pat)
                            lookups.appendlist(
                                name,
                                (
                                    new_matches,
                                    p_pattern + pat,
                                    {**defaults, **url_pattern.default_kwargs},
                                    {**self.pattern.converters, **url_pattern.pattern.converters, **converters}
                                )
                            )
                    for namespace, (prefix, sub_pattern) in url_pattern.namespace_dict.items():
                        current_converters = url_pattern.pattern.converters
                        sub_pattern.pattern.converters.update(current_converters)
                        namespaces[namespace] = (p_pattern + prefix, sub_pattern)
                    for app_name, namespace_list in url_pattern.app_dict.items():
                        apps.setdefault(app_name, []).extend(namespace_list)
                self._callback_strs.update(url_pattern._callback_strs)
        self._namespace_dict[language_code] = namespaces
        self._app_dict[language_code] = apps
        self._reverse_dict[language_code] = lookups
        self._populated = True
    finally:
        self._local.populating = False

def serialize_db_to_string(self):
    """
    Serialize all data in the database into a JSON string.
    Designed only for test runner usage; will not handle large
    amounts of data.
    """
    # Iteratively return every object for all models to serialize.
    def get_objects():
        from django.db.migrations.loader import MigrationLoader
        loader = MigrationLoader(self.connection)
        for app_config in apps.get_app_configs():
            if (
                app_config.models_module is not None and
                app_config.label in loader.migrated_apps and
                app_config.name not in settings.TEST_NON_SERIALIZED_APPS
            ):
                for model in app_config.get_models():
                    if (
                        model._meta.can_migrate(self.connection) and
                        router.allow_migrate_model(self.connection.alias, model)
                    ):
                        queryset = model._default_manager.using(
                            self.connection.alias,
                        ).order_by(model._meta.pk.name)
                        yield from queryset.iterator()
    # Serialize to a string
    out = StringIO()
    serializers.serialize("json", get_objects(), indent=None, stream=out)
    return out.getvalue()

def get_objects():
    from django.db.migrations.loader import MigrationLoader
    loader = MigrationLoader(self.connection)
    for app_config in apps.get_app_configs():
        if (
            app_config.models_module is not None and
            app_config.label in loader.migrated_apps and
            app_config.name not in settings.TEST_NON_SERIALIZED_APPS
        ):
            for model in app_config.get_models():
                if (
                    model._meta.can_migrate(self.connection) and
                    router.allow_migrate_model(self.connection.alias, model)
                ):
                    queryset = model._default_manager.using(
                        self.connection.alias,
                    ).order_by(model._meta.pk.name)
                    yield from queryset.iterator()

def _create_test_db(self, verbosity, autoclobber, keepdb=False):
    """
    Internal implementation - create the test db tables.
    """
    test_database_name = self._get_test_db_name()
    test_db_params = {
        'dbname': self.connection.ops.quote_name(test_database_name),
        'suffix': self.sql_table_creation_suffix(),
    }
    # Create the test database and connect to it.
    with self._nodb_cursor() as cursor:
        try:
            self._execute_create_test_db(cursor, test_db_params, keepdb)
        except Exception as e:
            # if we want to keep the db, then no need to do any of the below,
            # just return and skip it all.
            if keepdb:
                return test_database_name

            self.log('Got an error creating the test database: %s' % e)
            if not autoclobber:
                confirm = input(
                    "Type 'yes' if you would like to try deleting the test "
                    "database '%s', or 'no' to cancel: " % test_database_name)
            if autoclobber or confirm == 'yes':
                try:
                    if verbosity >= 1:
                        self.log('Destroying old test database for alias %s...' % (
                            self._get_database_display_str(verbosity, test_database_name),
                        ))
                    cursor.execute('DROP DATABASE %(dbname)s' % test_db_params)
                    self._execute_create_test_db(cursor, test_db_params, keepdb)
                except Exception as e:
                    self.log('Got an error recreating the test database: %s' % e)
                    sys.exit(2)
            else:
                self.log('Tests cancelled.')
                sys.exit(1)

    return test_database_name

def _execute_with_wrappers(self, sql, params, many, executor):
    context = {'connection': self.db, 'cursor': self}
    for wrapper in reversed(self.db.execute_wrappers):
        executor = functools.partial(wrapper, executor)
    return executor(sql, params, many, context)

def _execute(self, sql, params, *ignored_wrapper_args):
    self.db.validate_no_broken_transaction()
    with self.db.wrap_database_errors:
        if params is None:
            # params default might be backend specific.
            return self.cursor.execute(sql)
        else:
            return self.cursor.execute(sql, params)

def _executemany(self, sql, param_list, *ignored_wrapper_args):
    self.db.validate_no_broken_transaction()
    with self.db.wrap_database_errors:
        return self.cursor.executemany(sql, param_list)

def execute(self):
    """
    Given the command-line arguments, figure out which subcommand is being
    run, create a parser appropriate to that command, and run it.
    """
    try:
        subcommand = self.argv[1]
    except IndexError:
        subcommand = 'help'  # Display help if no arguments were given.

    # Preprocess options to extract --settings and --pythonpath.
    # These options could affect the commands that are available, so they
    # must be processed early.
    parser = CommandParser(
        prog=self.prog_name,
        usage='%(prog)s subcommand [options] [args]',
        add_help=False,
        allow_abbrev=False,
    )
    parser.add_argument('--settings')
    parser.add_argument('--pythonpath')
    parser.add_argument('args', nargs='*')  # catch-all
    try:
        options, args = parser.parse_known_args(self.argv[2:])
        handle_default_options(options)
    except CommandError:
        pass  # Ignore any option errors at this point.

    try:
        settings.INSTALLED_APPS
    except ImproperlyConfigured as exc:
        self.settings_exception = exc
    except ImportError as exc:
        self.settings_exception = exc

    if settings.configured:
        # Start the auto-reloading dev server even if the code is broken.
        # The hardcoded condition is a code smell but we can't rely on a
        # flag on the command class because we haven't located it yet.
        if subcommand == 'runserver' and '--noreload' not in self.argv:
            try:
                autoreload.check_errors(django.setup)()
            except Exception:
                # The exception will be raised later in the child process
                # started by the autoreloader. Pretend it didn't happen by
                # loading an empty list of applications.
                apps.all_models = defaultdict(dict)
                apps.app_configs = {}
                apps.apps_ready = apps.models_ready = apps.ready = True

                # Remove options not compatible with the built-in runserver
                # (e.g. options for the contrib.staticfiles' runserver).
                # Changes here require manually testing as described in
                # #27522.
                _parser = self.fetch_command('runserver').create_parser('django', 'runserver')
                _options, _args = _parser.parse_known_args(self.argv[2:])
                for _arg in _args:
                    self.argv.remove(_arg)

        # In all other cases, django.setup() is required to succeed.
        else:
            django.setup()

    self.autocomplete()

    if subcommand == 'help':
        if '--commands' in args:
            sys.stdout.write(self.main_help_text(commands_only=True) + '\n')
        elif not options.args:
            sys.stdout.write(self.main_help_text() + '\n')
        else:
            self.fetch_command(options.args[0]).print_help(self.prog_name, options.args[0])
    # Special-cases: We want 'django-admin --version' and
    # 'django-admin --help' to work, for backwards compatibility.
    elif subcommand == 'version' or self.argv[1:] == ['--version']:
        sys.stdout.write(django.get_version() + '\n')
    elif self.argv[1:] in (['--help'], ['-h']):
        sys.stdout.write(self.main_help_text() + '\n')
    else:
        self.fetch_command(subcommand).run_from_argv(self.argv)

def execute(self, *args, **options):
    """
    Try to execute this command, performing system checks if needed (as
    controlled by the ``requires_system_checks`` attribute, except if
    force-skipped).
    """
    if options['force_color'] and options['no_color']:
        raise CommandError("The --no-color and --force-color options can't be used together.")
    if options['force_color']:
        self.style = color_style(force_color=True)
    elif options['no_color']:
        self.style = no_style()
        self.stderr.style_func = None
    if options.get('stdout'):
        self.stdout = OutputWrapper(options['stdout'])
    if options.get('stderr'):
        self.stderr = OutputWrapper(options['stderr'])

    if self.requires_system_checks and not options['skip_checks']:
        if self.requires_system_checks == ALL_CHECKS:
            self.check()
        else:
            self.check(tags=self.requires_system_checks)
    if self.requires_migrations_checks:
        self.check_migrations()
    output = self.handle(*args, **options)
    if output:
        if self.output_transaction:
            connection = connections[options.get('database', DEFAULT_DB_ALIAS)]
            output = '%s\n%s\n%s' % (
                self.style.SQL_KEYWORD(connection.ops.start_transaction_sql()),
                output,
                self.style.SQL_KEYWORD(connection.ops.end_transaction_sql()),
            )
        self.stdout.write(output)
    return output

def handle(self, **options):
    # Execute the command and exit.
    if options['command']:
        exec(options['command'])
        return

    # Execute stdin if it has anything to read and exit.
    # Not supported on Windows due to select.select() limitations.
    if sys.platform != 'win32' and not sys.stdin.isatty() and select.select([sys.stdin], [], [], 0)[0]:
        exec(sys.stdin.read())
        return

    available_shells = [options['interface']] if options['interface'] else self.shells

    for shell in available_shells:
        try:
            return getattr(self, shell)(options)
        except ImportError:
            pass
    raise CommandError("Couldn't import {} interface.".format(shell))

