    # Return color with alpha channel only if the input spec has it
    # This is so that RGBA colors can override the Alpha property
    if to_rgba(val) != to_rgba(val, 1):
        return to_rgba(val)
    else:
        return to_rgb(val)

def infer_scale(self, arg: Any, data: Series) -> Scale:
    # TODO when inferring Continuous without data, verify type

    # TODO need to rethink the variable type system
    # (e.g. boolean, ordered categories as Ordinal, etc)..
    var_type = variable_type(data, boolean_type="categorical")

    if isinstance(arg, (dict, list)):
        return Nominal(arg)

    if isinstance(arg, tuple):
        if var_type == "categorical":
            # TODO It seems reasonable to allow a gradient mapping for nominal
            # scale but it also feels "technically" wrong. Should this infer
            # Ordinal with categorical data and, if so, verify orderedness?
            return Nominal(arg)
        return Continuous(arg)

    if callable(arg):
        return Continuous(arg)

    # TODO Do we accept str like "log", "pow", etc. for semantics?

    # TODO what about
    # - Temporal? (i.e. datetime)
    # - Boolean?

    if not isinstance(arg, str):
        msg = " ".join([
            f"A single scale argument for {self.variable} variables must be",
            f"a string, dict, tuple, list, or callable, not {type(arg)}."
        ])
        raise TypeError(msg)

    if arg in QUAL_PALETTES:
        return Nominal(arg)
    elif var_type == "numeric":
        return Continuous(arg)
    # TODO implement scales for date variables and any others.
    else:
        return Nominal(arg)

def _get_transform(self):

    arg = self.trans

    def get_param(method, default):
        if arg == method:
            return default
        return float(arg[len(method):])

    if arg is None:
        return _make_identity_transforms()
    elif isinstance(arg, tuple):
        return arg
    elif isinstance(arg, str):
        if arg == "ln":
            return _make_log_transforms()
        elif arg == "logit":
            base = get_param("logit", 10)
            return _make_logit_transforms(base)
        elif arg.startswith("log"):
            base = get_param("log", 10)
            return _make_log_transforms(base)
        elif arg.startswith("symlog"):
            c = get_param("symlog", 1)
            return _make_symlog_transforms(c)
        elif arg.startswith("pow"):
            exp = get_param("pow", 2)
            return _make_power_transforms(exp)
        elif arg == "sqrt":
            return _make_sqrt_transforms()
        else:
            raise ValueError(f"Unknown value provided for trans: {arg!r}")

def _parse_for_log_params(
    self, trans: str | TransFuncs | None
) -> tuple[float | None, float | None]:

    log_base = symlog_thresh = None
    if isinstance(trans, str):
        m = re.match(r"^log(\d*)", trans)
        if m is not None:
            log_base = float(m[1] or 10)
        m = re.match(r"symlog(\d*)", trans)
        if m is not None:
            symlog_thresh = float(m[1] or 1)
    return log_base, symlog_thresh

def _get_locators(self, locator, at, upto, count, every, between, minor):

    log_base, symlog_thresh = self._parse_for_log_params(self.trans)

    if locator is not None:
        major_locator = locator

    elif upto is not None:
        if log_base:
            major_locator = LogLocator(base=log_base, numticks=upto)
        else:
            major_locator = MaxNLocator(upto, steps=[1, 1.5, 2, 2.5, 3, 5, 10])

    elif count is not None:
        if between is None:
            # This is rarely useful (unless you are setting limits)
            major_locator = LinearLocator(count)
        else:
            if log_base or symlog_thresh:
                forward, inverse = self._get_transform()
                lo, hi = forward(between)
                ticks = inverse(np.linspace(lo, hi, num=count))
            else:
                ticks = np.linspace(*between, num=count)
            major_locator = FixedLocator(ticks)

    elif every is not None:
        if between is None:
            major_locator = MultipleLocator(every)
        else:
            lo, hi = between
            ticks = np.arange(lo, hi + every, every)
            major_locator = FixedLocator(ticks)

    elif at is not None:
        major_locator = FixedLocator(at)

    else:
        if log_base:
            major_locator = LogLocator(log_base)
        elif symlog_thresh:
            major_locator = SymmetricalLogLocator(linthresh=symlog_thresh, base=10)
        else:
            major_locator = AutoLocator()

    if minor is None:
        minor_locator = LogLocator(log_base, subs=None) if log_base else None
    else:
        if log_base:
            subs = np.linspace(0, log_base, minor + 2)[1:-1]
            minor_locator = LogLocator(log_base, subs=subs)
        else:
            minor_locator = AutoMinorLocator(minor + 1)

    return major_locator, minor_locator

def _get_formatter(self, locator, formatter, like, base, unit):

    log_base, symlog_thresh = self._parse_for_log_params(self.trans)
    if base is default:
        if symlog_thresh:
            log_base = 10
        base = log_base

    if formatter is not None:
        return formatter

    if like is not None:
        if isinstance(like, str):
            if "{x" in like or "{pos" in like:
                fmt = like
            else:
                fmt = f"{{x:{like}}}"
            formatter = StrMethodFormatter(fmt)
        else:
            formatter = FuncFormatter(like)

    elif base is not None:
        # We could add other log options if necessary
        formatter = LogFormatterSciNotation(base)

    elif unit is not None:
        if isinstance(unit, tuple):
            sep, unit = unit
        elif not unit:
            sep = ""
        else:
            sep = " "
        formatter = EngFormatter(unit, sep=sep)

    else:
        formatter = ScalarFormatter()

    return formatter

def close(self):
    """Closes the underlying file descriptor and releases the connection
    back to the pool.

    *Note: Should not normally need to be called explicitly.*
    """
    return self.raw.release_conn()

def prepare_method(self, method):
    """Prepares the given HTTP method."""
    self.method = method
    if self.method is not None:
        self.method = self.method.upper()

def prepare_url(self, url, params):
    """Prepares the given HTTP URL."""
    #: Accept objects that have string representations.
    try:
        url = unicode(url)
    except NameError:
        # We're on Python 3.
        url = str(url)
    except UnicodeDecodeError:
        pass

    # Don't do any URL preparation for oddball schemes
    if ':' in url and not url.lower().startswith('http'):
        self.url = url
        return

    # Support for unicode domain names and paths.
    scheme, auth, host, port, path, query, fragment = parse_url(url)

    if not scheme:
        raise MissingSchema("Invalid URL {0!r}: No schema supplied. "
                            "Perhaps you meant http://{0}?".format(url))

    if not host:
        raise InvalidURL("Invalid URL %r: No host supplied" % url)

    # Only want to apply IDNA to the hostname
    try:
        host = host.encode('idna').decode('utf-8')
    except UnicodeError:
        raise InvalidURL('URL has an invalid label.')

    # Carefully reconstruct the network location
    netloc = auth or ''
    if netloc:
        netloc += '@'
    netloc += host
    if port:
        netloc += ':' + str(port)

    # Bare domains aren't valid URLs.
    if not path:
        path = '/'

    if is_py2:
        if isinstance(scheme, str):
            scheme = scheme.encode('utf-8')
        if isinstance(netloc, str):
            netloc = netloc.encode('utf-8')
        if isinstance(path, str):
            path = path.encode('utf-8')
        if isinstance(query, str):
            query = query.encode('utf-8')
        if isinstance(fragment, str):
            fragment = fragment.encode('utf-8')

    enc_params = self._encode_params(params)
    if enc_params:
        if query:
            query = '%s&%s' % (query, enc_params)
        else:
            query = enc_params

    url = requote_uri(urlunparse([scheme, netloc, path, None, query, fragment]))
    self.url = url

def prepare_headers(self, headers):
    """Prepares the given HTTP headers."""

    if headers:
        self.headers = CaseInsensitiveDict((to_native_string(name), value) for name, value in headers.items())
    else:
        self.headers = CaseInsensitiveDict()

def run(self, mod: ast.Module) -> None:
    """Find all assert statements in *mod* and rewrite them."""
    if not mod.body:
        # Nothing to do.
        return

    # We'll insert some special imports at the top of the module, but after any
    # docstrings and __future__ imports, so first figure out where that is.
    doc = getattr(mod, "docstring", None)
    expect_docstring = doc is None
    if doc is not None and self.is_rewrite_disabled(doc):
        return
    pos = 0
    item = None
    for item in mod.body:
        if (
            expect_docstring
            and isinstance(item, ast.Expr)
            and isinstance(item.value, ast.Constant)
        ):
            doc = item.value.value
            if self.is_rewrite_disabled(doc):
                return
            expect_docstring = False
        elif (
            isinstance(item, ast.ImportFrom)
            and item.level == 0
            and item.module == "__future__"
        ):
            pass
        else:
            break
        pos += 1
    # Special case: for a decorated function, set the lineno to that of the
    # first decorator, not the `def`. Issue #4984.
    if isinstance(item, ast.FunctionDef) and item.decorator_list:
        lineno = item.decorator_list[0].lineno
    else:
        lineno = item.lineno
    # Now actually insert the special imports.
    if sys.version_info >= (3, 10):
        aliases = [
            ast.alias("builtins", "@py_builtins", lineno=lineno, col_offset=0),
            ast.alias(
                "_pytest.assertion.rewrite",
                "@pytest_ar",
                lineno=lineno,
                col_offset=0,
            ),
        ]
    else:
        aliases = [
            ast.alias("builtins", "@py_builtins"),
            ast.alias("_pytest.assertion.rewrite", "@pytest_ar"),
        ]
    imports = [
        ast.Import([alias], lineno=lineno, col_offset=0) for alias in aliases
    ]
    mod.body[pos:pos] = imports

    # Collect asserts.
    nodes: List[ast.AST] = [mod]
    while nodes:
        node = nodes.pop()
        for name, field in ast.iter_fields(node):
            if isinstance(field, list):
                new: List[ast.AST] = []
                for i, child in enumerate(field):
                    if isinstance(child, ast.Assert):
                        # Transform assert.
                        new.extend(self.visit(child))
                    else:
                        new.append(child)
                        if isinstance(child, ast.AST):
                            nodes.append(child)
                setattr(node, name, new)
            elif (
                isinstance(field, ast.AST)
                # Don't recurse into expressions as they can't contain
                # asserts.
                and not isinstance(field, ast.expr)
            ):
                nodes.append(field)

def _importtestmodule(self):
    # We assume we are only called once per module.
    importmode = self.config.getoption("--import-mode")
    try:
        mod = import_path(self.path, mode=importmode, root=self.config.rootpath)
    except SyntaxError as e:
        raise self.CollectError(
            ExceptionInfo.from_current().getrepr(style="short")
        ) from e
    except ImportPathMismatchError as e:
        raise self.CollectError(
            "import file mismatch:\n"
            "imported module %r has this __file__ attribute:\n"
            "  %s\n"
            "which is not the same as the test file we want to collect:\n"
            "  %s\n"
            "HINT: remove __pycache__ / .pyc files and/or use a "
            "unique basename for your test file modules" % e.args
        ) from e
    except ImportError as e:
        exc_info = ExceptionInfo.from_current()
        if self.config.getoption("verbose") < 2:
            exc_info.traceback = exc_info.traceback.filter(filter_traceback)
        exc_repr = (
            exc_info.getrepr(style="short")
            if exc_info.traceback
            else exc_info.exconly()
        )
        formatted_tb = str(exc_repr)
        raise self.CollectError(
            "ImportError while importing test module '{path}'.\n"
            "Hint: make sure your test modules/packages have valid Python names.\n"
            "Traceback:\n"
            "{traceback}".format(path=self.path, traceback=formatted_tb)
        ) from e
    except skip.Exception as e:
        if e.allow_module_level:
            raise
        raise self.CollectError(
            "Using pytest.skip outside of a test will skip the entire module. "
            "If that's your intention, pass `allow_module_level=True`. "
            "If you want to skip a specific test or an entire class, "
            "use the @pytest.mark.skip or @pytest.mark.skipif decorators."
        ) from e
    self.config.pluginmanager.consider_module(mod)
    return mod

def _inject_setup_module_fixture(self) -> None:
    """Inject a hidden autouse, module scoped fixture into the collected module object
    that invokes setUpModule/tearDownModule if either or both are available.

    Using a fixture to invoke this methods ensures we play nicely and unsurprisingly with
    other fixtures (#517).
    """
    has_nose = self.config.pluginmanager.has_plugin("nose")
    setup_module = _get_first_non_fixture_func(
        self.obj, ("setUpModule", "setup_module")
    )
    if setup_module is None and has_nose:
        # The name "setup" is too common - only treat as fixture if callable.
        setup_module = _get_first_non_fixture_func(self.obj, ("setup",))
        if not callable(setup_module):
            setup_module = None
    teardown_module = _get_first_non_fixture_func(
        self.obj, ("tearDownModule", "teardown_module")
    )
    if teardown_module is None and has_nose:
        teardown_module = _get_first_non_fixture_func(self.obj, ("teardown",))
        # Same as "setup" above - only treat as fixture if callable.
        if not callable(teardown_module):
            teardown_module = None

    if setup_module is None and teardown_module is None:
        return

    @fixtures.fixture(
        autouse=True,
        scope="module",
        # Use a unique name to speed up lookup.
        name=f"_xunit_setup_module_fixture_{self.obj.__name__}",
    )
    def xunit_setup_module_fixture(request) -> Generator[None, None, None]:
        if setup_module is not None:
            _call_with_optional_argument(setup_module, request.module)
        yield
        if teardown_module is not None:
            _call_with_optional_argument(teardown_module, request.module)

    self.obj.__pytest_setup_module = xunit_setup_module_fixture

def _inject_setup_function_fixture(self) -> None:
    """Inject a hidden autouse, function scoped fixture into the collected module object
    that invokes setup_function/teardown_function if either or both are available.

    Using a fixture to invoke this methods ensures we play nicely and unsurprisingly with
    other fixtures (#517).
    """
    setup_function = _get_first_non_fixture_func(self.obj, ("setup_function",))
    teardown_function = _get_first_non_fixture_func(
        self.obj, ("teardown_function",)
    )
    if setup_function is None and teardown_function is None:
        return

    @fixtures.fixture(
        autouse=True,
        scope="function",
        # Use a unique name to speed up lookup.
        name=f"_xunit_setup_function_fixture_{self.obj.__name__}",
    )
    def xunit_setup_function_fixture(request) -> Generator[None, None, None]:
        if request.instance is not None:
            # in this case we are bound to an instance, so we need to let
            # setup_method handle this
            yield
            return
        if setup_function is not None:
            _call_with_optional_argument(setup_function, request.function)
        yield
        if teardown_function is not None:
            _call_with_optional_argument(teardown_function, request.function)

    self.obj.__pytest_setup_function = xunit_setup_function_fixture

def repr(self, x: Any) -> str:
    try:
        s = super().repr(x)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc:
        s = _format_repr_exception(exc, x)
    return _ellipsize(s, self.maxsize)

def _format_repr_exception(exc: BaseException, obj: Any) -> str:
    try:
        exc_info = _try_repr_or_str(exc)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc:
        exc_info = "unpresentable exception ({})".format(_try_repr_or_str(exc))
    return "<[{} raised in repr()] {} object at 0x{:x}>".format(
        exc_info, obj.__class__.__name__, id(obj)
    )

def _try_repr_or_str(obj):
    try:
        return repr(obj)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException:
        return '{}("{}")'.format(type(obj).__name__, obj)

def repr_excinfo(self, excinfo: ExceptionInfo) -> "ExceptionChainRepr":
    repr_chain = (
        []
    )  # type: List[Tuple[ReprTraceback, Optional[ReprFileLocation], Optional[str]]]
    e = excinfo.value
    excinfo_ = excinfo  # type: Optional[ExceptionInfo]
    descr = None
    seen = set()  # type: Set[int]
    while e is not None and id(e) not in seen:
        seen.add(id(e))
        if excinfo_:
            reprtraceback = self.repr_traceback(excinfo_)
            reprcrash = excinfo_._getreprcrash()  # type: Optional[ReprFileLocation]
        else:
            # fallback to native repr if the exception doesn't have a traceback:
            # ExceptionInfo objects require a full traceback to work
            reprtraceback = ReprTracebackNative(
                traceback.format_exception(type(e), e, None)
            )
            reprcrash = None

        repr_chain += [(reprtraceback, reprcrash, descr)]
        if e.__cause__ is not None and self.chain:
            e = e.__cause__
            excinfo_ = (
                ExceptionInfo((type(e), e, e.__traceback__))
                if e.__traceback__
                else None
            )
            descr = "The above exception was the direct cause of the following exception:"
        elif (
            e.__context__ is not None and not e.__suppress_context__ and self.chain
        ):
            e = e.__context__
            excinfo_ = (
                ExceptionInfo((type(e), e, e.__traceback__))
                if e.__traceback__
                else None
            )
            descr = "During handling of the above exception, another exception occurred:"
        else:
            e = None
    repr_chain.reverse()
    return ExceptionChainRepr(repr_chain)

def repr_traceback(self, excinfo: ExceptionInfo) -> "ReprTraceback":
    traceback = excinfo.traceback
    if self.tbfilter:
        traceback = traceback.filter()

    if excinfo.errisinstance(RecursionError):
        traceback, extraline = self._truncate_recursive_traceback(traceback)
    else:
        extraline = None

    last = traceback[-1]
    entries = []
    for index, entry in enumerate(traceback):
        einfo = (last == entry) and excinfo or None
        reprentry = self.repr_traceback_entry(entry, einfo)
        entries.append(reprentry)
    return ReprTraceback(entries, extraline, style=self.style)

def repr_traceback_entry(
    self, entry: TracebackEntry, excinfo: Optional[ExceptionInfo] = None
) -> "ReprEntry":
    import _pytest._code

    source = self._getentrysource(entry)
    if source is None:
        source = _pytest._code.Source("???")
        line_index = 0
    else:
        line_index = entry.lineno - entry.getfirstlinesource()

    lines = []  # type: List[str]
    style = entry._repr_style if entry._repr_style is not None else self.style
    if style in ("short", "long"):
        short = style == "short"
        reprargs = self.repr_args(entry) if not short else None
        s = self.get_source(source, line_index, excinfo, short=short)
        lines.extend(s)
        if short:
            message = "in %s" % (entry.name)
        else:
            message = excinfo and excinfo.typename or ""
        path = self._makepath(entry.path)
        reprfileloc = ReprFileLocation(path, entry.lineno + 1, message)
        localsrepr = self.repr_locals(entry.locals)
        return ReprEntry(lines, reprargs, localsrepr, reprfileloc, style)
    if excinfo:
        lines.extend(self.get_exconly(excinfo, indent=4))
    return ReprEntry(lines, None, None, None, style)

def _check_solver(solver, penalty, dual):
    all_solvers = ['liblinear', 'newton-cg', 'lbfgs', 'sag', 'saga']
    if solver not in all_solvers:
        raise ValueError("Logistic Regression supports only solvers in %s, got"
                         " %s." % (all_solvers, solver))

    all_penalties = ['l1', 'l2', 'elasticnet', 'none']
    if penalty not in all_penalties:
        raise ValueError("Logistic Regression supports only penalties in %s,"
                         " got %s." % (all_penalties, penalty))

    if solver not in ['liblinear', 'saga'] and penalty not in ('l2', 'none'):
        raise ValueError("Solver %s supports only 'l2' or 'none' penalties, "
                         "got %s penalty." % (solver, penalty))
    if solver != 'liblinear' and dual:
        raise ValueError("Solver %s supports only "
                         "dual=False, got dual=%s" % (solver, dual))

    if penalty == 'elasticnet' and solver != 'saga':
        raise ValueError("Only 'saga' solver supports elasticnet penalty,"
                         " got solver={}.".format(solver))

    if solver == 'liblinear' and penalty == 'none':
        raise ValueError(
            "penalty='none' is not supported for the liblinear solver"
        )

    return solver

def _check_multi_class(multi_class, solver, n_classes):
    if multi_class == 'auto':
        if solver == 'liblinear':
            multi_class = 'ovr'
        elif n_classes > 2:
            multi_class = 'multinomial'
        else:
            multi_class = 'ovr'
    if multi_class not in ('multinomial', 'ovr'):
        raise ValueError("multi_class should be 'multinomial', 'ovr' or "
                         "'auto'. Got %s." % multi_class)
    if multi_class == 'multinomial' and solver == 'liblinear':
        raise ValueError("Solver %s does not support "
                         "a multinomial backend." % solver)
    return multi_class

def _auto_wrap_is_configured(estimator):
    """Return True if estimator is configured for auto-wrapping the transform method.

    `_SetOutputMixin` sets `_sklearn_auto_wrap_output_keys` to `set()` if auto wrapping
    is manually disabled.
    """
    auto_wrap_output_keys = getattr(estimator, "_sklearn_auto_wrap_output_keys", set())
    return (
        hasattr(estimator, "get_feature_names_out")
        and "transform" in auto_wrap_output_keys
    )

def skip_member(obj: Any, name: str, objtype: str) -> bool:
    try:
        return app.emit_firstresult('autodoc-skip-member', objtype, name,
                                    obj, False, {})
    except Exception as exc:
        logger.warning(__('autosummary: failed to determine %r to be documented, '
                          'the following exception was raised:\n%s'),
                       name, exc, type='autosummary')
        return False

def get_import_prefixes_from_env(env: BuildEnvironment) -> List[str]:
    """
    Obtain current Python import prefixes (for `import_by_name`)
    from ``document.env``
    """
    prefixes = [None]  # type: List[str]

    currmodule = env.ref_context.get('py:module')
    if currmodule:
        prefixes.insert(0, currmodule)

    currclass = env.ref_context.get('py:class')
    if currclass:
        if currmodule:
            prefixes.insert(0, currmodule + "." + currclass)
        else:
            prefixes.insert(0, currclass)

    return prefixes

def import_by_name(name: str, prefixes: List[str] = [None]) -> Tuple[str, Any, Any, str]:
    """Import a Python object that has the given *name*, under one of the
    *prefixes*.  The first name that succeeds is used.
    """
    tried = []
    for prefix in prefixes:
        try:
            if prefix:
                prefixed_name = '.'.join([prefix, name])
            else:
                prefixed_name = name
            obj, parent, modname = _import_by_name(prefixed_name)
            return prefixed_name, obj, parent, modname
        except ImportError:
            tried.append(prefixed_name)
    raise ImportError('no module named %s' % ' or '.join(tried))

def safe_getmembers(object: Any, predicate: Callable[[str], bool] = None,
                    attr_getter: Callable = safe_getattr) -> List[Tuple[str, Any]]:
    """A version of inspect.getmembers() that uses safe_getattr()."""
    warnings.warn('safe_getmembers() is deprecated', RemovedInSphinx40Warning, stacklevel=2)

    results = []  # type: List[Tuple[str, Any]]
    for key in dir(object):
        try:
            value = attr_getter(object, key, None)
        except AttributeError:
            continue
        if not predicate or predicate(value):
            results.append((key, value))
    results.sort()
    return results

def get_module_attrs(members: Any) -> Tuple[List[str], List[str]]:
    """Find module attributes with docstrings."""
    attrs, public = [], []
    try:
        analyzer = ModuleAnalyzer.for_module(name)
        attr_docs = analyzer.find_attr_docs()
        for namespace, attr_name in attr_docs:
            if namespace == '' and attr_name in members:
                attrs.append(attr_name)
                if not attr_name.startswith('_'):
                    public.append(attr_name)
    except PycodeError:
        pass    # give up if ModuleAnalyzer fails to parse code
    return public, attrs

def generate_autosummary_content(name: str, obj: Any, parent: Any,
                                 template: AutosummaryRenderer, template_name: str,
                                 imported_members: bool, app: Any,
                                 recursive: bool, context: Dict) -> str:
    doc = get_documenter(app, obj, parent)

    def skip_member(obj: Any, name: str, objtype: str) -> bool:
        try:
            return app.emit_firstresult('autodoc-skip-member', objtype, name,
                                        obj, False, {})
        except Exception as exc:
            logger.warning(__('autosummary: failed to determine %r to be documented, '
                              'the following exception was raised:\n%s'),
                           name, exc, type='autosummary')
            return False

    def get_members(obj: Any, types: Set[str], include_public: List[str] = [],
                    imported: bool = True) -> Tuple[List[str], List[str]]:
        items = []  # type: List[str]
        public = []  # type: List[str]
        for name in dir(obj):
            try:
                value = safe_getattr(obj, name)
            except AttributeError:
                continue
            documenter = get_documenter(app, value, obj)
            if documenter.objtype in types:
                # skip imported members if expected
                if imported or getattr(value, '__module__', None) == obj.__name__:
                    skipped = skip_member(value, name, documenter.objtype)
                    if skipped is True:
                        pass
                    elif skipped is False:
                        # show the member forcedly
                        items.append(name)
                        public.append(name)
                    else:
                        items.append(name)
                        if name in include_public or not name.startswith('_'):
                            # considers member as public
                            public.append(name)
        return public, items

    def get_module_attrs(members: Any) -> Tuple[List[str], List[str]]:
        """Find module attributes with docstrings."""
        attrs, public = [], []
        try:
            analyzer = ModuleAnalyzer.for_module(name)
            attr_docs = analyzer.find_attr_docs()
            for namespace, attr_name in attr_docs:
                if namespace == '' and attr_name in members:
                    attrs.append(attr_name)
                    if not attr_name.startswith('_'):
                        public.append(attr_name)
        except PycodeError:
            pass    # give up if ModuleAnalyzer fails to parse code
        return public, attrs

    def get_modules(obj: Any) -> Tuple[List[str], List[str]]:
        items = []  # type: List[str]
        for _, modname, ispkg in pkgutil.iter_modules(obj.__path__):
            fullname = name + '.' + modname
            items.append(fullname)
        public = [x for x in items if not x.split('.')[-1].startswith('_')]
        return public, items

    ns = {}  # type: Dict[str, Any]
    ns.update(context)

    if doc.objtype == 'module':
        ns['members'] = dir(obj)
        ns['functions'], ns['all_functions'] = \
            get_members(obj, {'function'}, imported=imported_members)
        ns['classes'], ns['all_classes'] = \
            get_members(obj, {'class'}, imported=imported_members)
        ns['exceptions'], ns['all_exceptions'] = \
