def _print_Product(self, expr):
    from sympy.concrete.products import Product
    from sympy.printing.pretty.stringpict import stringPict, prettyForm

    if expr.limits:
        def parenthesize(limit):
            if len(limit) == 3:
                return (limit[0], limit[1], limit[2])
            else:
                return (limit[0], limit[1], limit[2], limit[3])

        limits = list(map(parenthesize, expr.limits))
        top = self._print(expr.function)
        bottom = stringPict()
        for limit in limits:
            bottom = bottom.below(self._print(limit[0]) + stringPict(' = ') + self._print(limit[1]))
            if len(limit) == 4:
                bottom = bottom.below(self._print(limit[2]) + stringPict(' to ') + self._print(limit[3]))
            else:
                bottom = bottom.below(self._print(limit[2]))
        prod = stringPict('∏')
        if self._use_unicode():
            prod = stringPict('∏')
        else:
            prod = stringPict('P')
        prod = prod.below(top)
        prod = prod.below(bottom)
        return prettyForm(prod)
    else:
        return self._print(expr.function)
